python3 - <<'PY'
import msgpack,io,collections,json
b=open('inputs/chall/unknown.data','rb').read()
def hook(pairs): return ('MAP',pairs)
u=msgpack.Unpacker(io.BytesIO(b),raw=True,strict_map_key=False,object_pairs_hook=hook)
c=collections.Counter(); first=[]; last=[]; count=0; err=None; lastend=0
try:
 for v in u:
  count+=1; c[type(v).__name__]+=1; lastend=u.tell()
  if len(first)<12:first.append({'index':count-1,'end':lastend,'type':type(v).__name__,'len':len(v) if isinstance(v,(bytes,str,list,tuple)) else None})
  last.append({'index':count-1,'end':lastend,'type':type(v).__name__,'len':len(v) if isinstance(v,(bytes,str,list,tuple)) else None})
  if len(last)>12:last.pop(0)
except Exception as e: err={'type':type(e).__name__,'offset':u.tell(),'message':str(e)[:180]}
print('total_bytes',len(b),'decoded_values',count,'last_complete_end_offset',lastend,'type_counts',dict(c),'error',err)
print('first_items',json.dumps(first))
print('last_items',json.dumps(last))
PY
